// Cold Email Engine — Prisma-backed LeadStore for the bulk importer.
//
// The ONE adapter that maps lib/coldemail/import.ts's store-agnostic ingest logic
// onto Prisma. Shared by the admin server action (lib/actions-coldemail.ts) and the
// operator CLI (scripts/import-leads.ts) so both go through identical, tested,
// idempotent dedup logic. Plain module (no "use server") — safe to import from a
// tsx script or the worker.

import { db } from "@/lib/db";
import { normalizeEmail, emailDomain } from "@/lib/coldemail/compliance";
import type { LeadStore, NormalizedLead, ExistingContact } from "@/lib/coldemail/import";

/** Build a LeadStore over the live Prisma client, stamping `source` on new Businesses. */
export function prismaLeadStore(businessSource = "import"): LeadStore {
  return {
    async findContact(email: string): Promise<ExistingContact | null> {
      const c = await db.contact.findUnique({
        where: { email: normalizeEmail(email) },
        select: { id: true, businessId: true, emailStatus: true, fullName: true, title: true },
      });
      return c ? { ...c, emailStatus: c.emailStatus as string } : null;
    },

    async isSuppressed(email: string): Promise<boolean> {
      const e = normalizeEmail(email);
      const domain = emailDomain(e);
      const hit = await db.suppression.findFirst({
        where: {
          scope: "GLOBAL",
          OR: [{ email: e }, ...(domain ? [{ domain }] : [])],
        },
        select: { id: true },
      });
      return !!hit;
    },

    async createBusiness(data: NormalizedLead["business"], _batchId: string | null): Promise<string> {
      const b = await db.business.create({ data: { ...data, source: businessSource } });
      return b.id;
    },

    async createContact(input, batchId): Promise<string> {
      const c = await db.contact.create({
        data: {
          businessId: input.businessId,
          email: normalizeEmail(input.email),
          fullName: input.fullName,
          title: input.title,
          emailStatus: "UNVERIFIED",
          ...(batchId ? { importBatchId: batchId } : {}),
        },
        select: { id: true },
      });
      return c.id;
    },

    async updateContact(id, input, batchId): Promise<void> {
      const data: Record<string, unknown> = {};
      if (input.fullName) data.fullName = input.fullName;
      if (input.title) data.title = input.title;
      if (batchId) data.importBatchId = batchId;
      if (Object.keys(data).length === 0) return;
      await db.contact.update({ where: { id }, data });
    },

    async addToList(contactId, listId): Promise<void> {
      // Idempotent — the unique (listId, contactId) makes a repeat a no-op.
      await db.emailListMember.createMany({ data: [{ contactId, listId }], skipDuplicates: true });
    },

    async recordConsent(contactId, source): Promise<void> {
      await db.consentRecord.create({
        data: { contactId, basis: "LEGITIMATE_INTEREST", source: source.slice(0, 120) },
      });
    },
  };
}

